<div x-data="rambuIndex()" x-init="load()" x-cloak><div class="mb-7 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p class="text-sm text-slate-600">Inventaris rambu lalu lintas</p><h2 class="mt-1 text-2xl font-semibold tracking-tight text-navy-900">Data Rambu</h2></div><a href="{{ route('assets.rambu.create') }}" class="action-button-primary">+ Tambah Rambu</a></div><div x-show="notice" class="mb-4 rounded-xl border border-teal-200 bg-teal-50 px-4 py-3 text-sm text-teal-800" x-text="notice"></div><section class="rounded-2xl border border-border bg-white p-4 shadow-sm"><div class="grid gap-3 md:grid-cols-3"><div><label class="field-label" for="rambu-search">Cari kode, alamat, kecamatan, jenis</label><input id="rambu-search" x-model="search" class="field-input" type="search"></div><div><label class="field-label" for="rambu-status">Status</label><select id="rambu-status" x-model="filters.status" class="field-input"><option value="">Semua</option><option>baik</option><option>rusak</option><option>perbaikan</option></select></div><div><label class="field-label" for="rambu-type">Jenis rambu</label><input id="rambu-type" x-model="filters.type" class="field-input" placeholder="peringatan, larangan..."></div><div><label class="field-label" for="rambu-year">Tahun anggaran</label><select id="rambu-year" x-model="filters.year" class="field-input"><option value="">Semua tahun</option><template x-for="year in years" :key="year"><option :value="String(year)" x-text="year"></option></template></select></div></div></section><div x-show="error" class="mt-5 rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700" x-text="error"></div><section class="mt-5 overflow-hidden rounded-2xl border border-border bg-white shadow-sm"><div class="border-b border-border px-5 py-4"><h3 class="font-semibold text-navy-900">Daftar aset</h3><p class="mt-1 text-xs text-slate-500" x-text="`${filtered.length} aset ditampilkan`"></p></div><div class="overflow-x-auto"><table class="w-full min-w-[980px] text-left text-sm"><thead class="bg-slate-50 text-xs uppercase tracking-wider text-slate-500"><tr><th class="px-5 py-3">Kode</th><th class="px-5 py-3">Jenis</th><th class="px-5 py-3">Alamat</th><th class="px-5 py-3">Kecamatan</th><th class="px-5 py-3">Tahun</th><th class="px-5 py-3">Status</th><th class="px-5 py-3 text-right">Aksi</th></tr></thead><tbody class="divide-y divide-border"><template x-for="item in filtered" :key="item.id"><tr class="hover:bg-slate-50"><td class="px-5 py-4 font-semibold text-navy-900" x-text="code(item)"></td><td class="px-5 py-4 text-slate-600" x-text="item.jenis_rambu"></td><td class="px-5 py-4 text-slate-600" x-text="item.alamat"></td><td class="px-5 py-4 text-slate-600" x-text="item.desa?.kecamatan?.kecamatan||item.desa?.kec_dtks||'-'"></td><td class="px-5 py-4 text-slate-600" x-text="item.tahun_anggaran||'-'"></td><td class="px-5 py-4"><span class="inline-flex rounded-full px-2.5 py-1 text-xs" :class="statusClass(item.status)" x-text="item.status"></span></td><td class="px-5 py-4"><div class="flex justify-end gap-2"><a :href="`/assets/rambu/${item.id}`" class="action-link">Detail</a><a :href="`/assets/rambu/${item.id}/edit`" class="action-link">Edit</a><button x-show="$store.auth.role==='admin'" @click="remove(item)" class="action-link text-red-600">Hapus</button></div></td></tr></template></tbody></table></div><div x-show="!loading&&!error&&!filtered.length" class="px-5 py-16 text-center text-sm text-slate-500">Tidak ada data Rambu.</div></section></div>
<script>function rambuIndex(){return{assets:[],loading:true,error:'',notice:new URLSearchParams(location.search).get('success')==='created'?'Rambu berhasil ditambahkan.':new URLSearchParams(location.search).get('success')==='updated'?'Rambu berhasil diperbarui.':'',search:'',filters:{status:'',type:'',year:''},get years(){return [...new Set(this.assets.map(x=>x.tahun_anggaran).filter(Boolean))].sort((a,b)=>b-a)},get filtered(){const q=this.search.toLowerCase().trim();return this.assets.filter(x=>(!q||[this.code(x),x.alamat,x.jenis_rambu,x.desa?.kecamatan?.kecamatan,x.desa?.kec_dtks].filter(Boolean).join(' ').toLowerCase().includes(q))&&(!this.filters.status||x.status===this.filters.status)&&(!this.filters.type||String(x.jenis_rambu||'').toLowerCase().includes(this.filters.type.toLowerCase()))&&(!this.filters.year||String(x.tahun_anggaran)===this.filters.year))},async load(){try{const r=await window.axios.get('/api/rambu');this.assets=Array.isArray(r.data)?r.data:r.data?.data||[]}catch(e){this.error=e.response?.data?.message||'Gagal memuat data Rambu.'}finally{this.loading=false}},code(x){return`RAMBU-${String(x.id).padStart(4,'0')}`},statusClass(s){return s==='baik'?'bg-teal-100 text-teal-800':s==='rusak'?'bg-red-100 text-red-800':'bg-yellow-100 text-yellow-800'},async remove(x){if(!confirm(`Hapus ${this.code(x)}?`))return;try{await window.axios.delete(`/api/rambu/${x.id}`);this.notice='Rambu berhasil dihapus.';await this.load()}catch(e){this.error=e.response?.data?.message||'Gagal menghapus Rambu.'}}}}</script>
@endsection
